{
  "items": [
    {
      "name": "Int.log",
      "module_name": "Mathlib.Data.Int.Log",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semifield R] → [inst_1 : LinearOrder R] → [FloorSemiring R] → ℕ → R → ℤ"
    },
    {
      "name": "Nat.clog_pow_left",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ (b k n : ℕ), Nat.clog (b ^ k) n = (Nat.clog b n + (k - 1)) / k"
    },
    {
      "name": "Real.log_pow",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Basic",
      "kind": "theorem",
      "type": "∀ (x : ℝ) (n : ℕ), Real.log (x ^ n) = ↑n * Real.log x"
    },
    {
      "name": "Real.floor_logb_natCast",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Base",
      "kind": "theorem",
      "type": "∀ {b : ℕ} {r : ℝ}, 0 ≤ r → ⌊Real.logb (↑b) r⌋ = Int.log b r"
    },
    {
      "name": "Int.log_of_one_le_right",
      "module_name": "Mathlib.Data.Int.Log",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semifield R] [inst_1 : LinearOrder R] [inst_2 : FloorSemiring R] (b : ℕ) {r : R},\n  1 ≤ r → Int.log b r = ↑(Nat.log b ⌊r⌋₊)"
    },
    {
      "name": "Real.natFloor_logb_natCast",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Base",
      "kind": "theorem",
      "type": "∀ (b n : ℕ), ⌊Real.logb ↑b ↑n⌋₊ = Nat.log b n"
    },
    {
      "name": "Real.natLog_le_logb",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Base",
      "kind": "theorem",
      "type": "∀ (a b : ℕ), ↑(Nat.log b a) ≤ Real.logb ↑b ↑a"
    },
    {
      "name": "Nat.le_pow_iff_clog_le",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b : ℕ}, 1 < b → ∀ {x y : ℕ}, x ≤ b ^ y ↔ Nat.clog b x ≤ y"
    }
  ]
}
